def to_locale(language):
    """Turn a language name (en-us) into a locale name (en_US).

    Support language tags containing multiple subtags (e.g. script and
    region, ``zh-hans-cn`` -> ``zh_Hans_CN``) so they can be used with URL
    language prefixes and gettext locale fallbacks.
    """
    if not language:
        return language
    base, has_modifier, modifier = str(language).partition('@')
    parts = base.split('-')

    if len(parts) == 1:
        # No region specified. Keep behavior compatible with the previous
        # implementation which lowercased only the language part.
        locale = base[:3].lower() + base[3:]
    else:
        lang = parts[0].lower()
        subtags = []
        for subtag in parts[1:]:
            if len(subtag) == 4 and subtag.isalpha():
                # Script code: titlecase (Latn).
                subtags.append(subtag.title())
            elif (len(subtag) == 2 and subtag.isalpha()) or (len(subtag) == 3 and subtag.isdigit()):
                # Region code: uppercase (US) or keep digits (419).
                subtags.append(subtag.upper())
            else:
                subtags.append(subtag)
        locale = '_'.join([lang, *subtags])

    if has_modifier:
        locale = f"{locale}@{modifier}"
    return locale

